using System;using System.IO;using System.Reflection;using System.Security.Cryptography;using Unity.Burst;using Unity.Collections;using Unity.Jobs;using Unity.Mathematics;using UnityEngine;using Game.Simulation;
namespace Game.Tests.Editor{
public static class NativeSourceMathWitness{
 [Serializable]public sealed class Input{public string kind;public LookCase[] look;public AriaCase[] aria;}
 [Serializable]public sealed class LookCase{public string id;public int[] forwardBits;public int[] upBits;}
 [Serializable]public sealed class AriaCase{public string id;public int[] aBits;public int[] bBits;}
 [Serializable]public sealed class Output{public string kind="NativeManagedAndBurstSourceMathWitness";public string scope="Reference capture only; no runtime or mission admission";public string inputSha256;public string mathAssemblyPath,mathAssemblySha256,mathModuleMvid;public string ariaAssemblyPath,ariaAssemblySha256,ariaModuleMvid;public string floatMode="Default (same attribute defaults as UnitGridMovementSystem)";public bool burstDiscardProof;public LookResult[] look;public AriaResult[] aria;}
 [Serializable]public sealed class LookResult{public string id;public int[] forwardBits,upBits,managedBits,burstBits;}
 [Serializable]public sealed class AriaResult{public string id;public int[] aBits,bBits,deltaBits;public int managedOriginalSquaredBits,managedOriginalSquaredDistanceBits,burstOriginalSquaredDistanceBits,burstMathDistanceSqBits;}
 [BurstCompile(CompileSynchronously=true)]struct Job:IJob{
  [ReadOnly]public NativeArray<float3> Forward,Up,A,B;public NativeArray<float4> Look;public NativeArray<float> Aria,Math;public NativeArray<int> Managed;
  [BurstDiscard]static void MarkManaged(ref int marker){marker=1;}
  public void Execute(){int marker=0;MarkManaged(ref marker);Managed[0]=marker;for(int i=0;i<Forward.Length;i++)Look[i]=quaternion.LookRotationSafe(Forward[i],Up[i]).value;for(int i=0;i<A.Length;i++){var a=A[i];var b=B[i];Aria[i]=AriaGroundApproachPolicy.SquaredDistance(new AriaGroundPosition(a.x,a.y,a.z),new AriaGroundPosition(b.x,b.y,b.z));Math[i]=math.distancesq(a,b);}}
 }
 static int Bits(float value)=>BitConverter.ToInt32(BitConverter.GetBytes(value),0);static float Value(int value)=>BitConverter.ToSingle(BitConverter.GetBytes(value),0);static float3 Vector(int[] bits){if(bits==null||bits.Length!=3)throw new InvalidDataException("Exact three scalar bits required");return new float3(Value(bits[0]),Value(bits[1]),Value(bits[2]));}static int[] Raw(float3 value)=>new[]{Bits(value.x),Bits(value.y),Bits(value.z)};static int[] Raw(float4 value)=>new[]{Bits(value.x),Bits(value.y),Bits(value.z),Bits(value.w)};static string Hash(byte[] bytes){using var sha=SHA256.Create();return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}static void Need(bool value,string reason){if(!value)throw new InvalidOperationException(reason);}
 public static void Run(){string inputPath=Environment.GetEnvironmentVariable("WARLINE_SOURCE_MATH_WITNESS_INPUT");string outputPath=Environment.GetEnvironmentVariable("WARLINE_SOURCE_MATH_WITNESS_OUTPUT");Need(!string.IsNullOrEmpty(inputPath)&&!string.IsNullOrEmpty(outputPath),"Explicit witness input/output paths required");byte[] bytes=File.ReadAllBytes(inputPath);Need(bytes.Length<=4*1024*1024,"Finite witness file required");Need(!File.Exists(outputPath),"Fresh witness output required");var input=JsonUtility.FromJson<Input>(System.Text.Encoding.UTF8.GetString(bytes));Need(input!=null&&input.kind=="ExactSourceMathWitnessInput","Explicit exact captured witness kind required");var looks=input.look??Array.Empty<LookCase>();var arias=input.aria??Array.Empty<AriaCase>();Need(looks.Length>0&&looks.Length<=128&&arias.Length>0&&arias.Length<=1024,"Finite captured look and observer witness rows required");Need(BurstCompiler.IsEnabled,"Actual Burst must be enabled for reference capture");
  var sourceForward=new float3[looks.Length];var sourceUp=new float3[looks.Length];var sourceA=new float3[arias.Length];var sourceB=new float3[arias.Length];for(int i=0;i<looks.Length;i++){sourceForward[i]=Vector(looks[i].forwardBits);sourceUp[i]=Vector(looks[i].upBits);}for(int i=0;i<arias.Length;i++){sourceA[i]=Vector(arias[i].aBits);sourceB[i]=Vector(arias[i].bBits);}using var forward=new NativeArray<float3>(sourceForward,Allocator.TempJob);using var up=new NativeArray<float3>(sourceUp,Allocator.TempJob);using var a=new NativeArray<float3>(sourceA,Allocator.TempJob);using var b=new NativeArray<float3>(sourceB,Allocator.TempJob);using var look=new NativeArray<float4>(looks.Length,Allocator.TempJob);using var aria=new NativeArray<float>(arias.Length,Allocator.TempJob);using var distance=new NativeArray<float>(arias.Length,Allocator.TempJob);using var managed=new NativeArray<int>(1,Allocator.TempJob);new Job{Forward=forward,Up=up,A=a,B=b,Look=look,Aria=aria,Math=distance,Managed=managed}.Schedule().Complete();Need(managed[0]==0,"BurstDiscard witness proves job fell back to managed execution");
  var squared=(Func<AriaGroundPosition,float>)Delegate.CreateDelegate(typeof(Func<AriaGroundPosition,float>),typeof(AriaGroundApproachPolicy).GetMethod("Squared",BindingFlags.Static|BindingFlags.NonPublic));var output=new Output{inputSha256=Hash(bytes),burstDiscardProof=true,look=new LookResult[looks.Length],aria=new AriaResult[arias.Length]};for(int i=0;i<looks.Length;i++)output.look[i]=new LookResult{id=looks[i].id,forwardBits=Raw(forward[i]),upBits=Raw(up[i]),managedBits=Raw(quaternion.LookRotationSafe(forward[i],up[i]).value),burstBits=Raw(look[i])};for(int i=0;i<arias.Length;i++){var aa=new AriaGroundPosition(a[i].x,a[i].y,a[i].z);var bb=new AriaGroundPosition(b[i].x,b[i].y,b[i].z);var delta=new AriaGroundPosition(aa.X-bb.X,aa.Y-bb.Y,aa.Z-bb.Z);output.aria[i]=new AriaResult{id=arias[i].id,aBits=Raw(a[i]),bBits=Raw(b[i]),deltaBits=new[]{Bits(delta.X),Bits(delta.Y),Bits(delta.Z)},managedOriginalSquaredBits=Bits(squared(delta)),managedOriginalSquaredDistanceBits=Bits(AriaGroundApproachPolicy.SquaredDistance(aa,bb)),burstOriginalSquaredDistanceBits=Bits(aria[i]),burstMathDistanceSqBits=Bits(distance[i])};}
  var math=typeof(quaternion).Assembly;var policy=typeof(AriaGroundApproachPolicy).Assembly;output.mathAssemblyPath=math.Location;output.mathAssemblySha256=Hash(File.ReadAllBytes(math.Location));output.mathModuleMvid=math.ManifestModule.ModuleVersionId.ToString();output.ariaAssemblyPath=policy.Location;output.ariaAssemblySha256=Hash(File.ReadAllBytes(policy.Location));output.ariaModuleMvid=policy.ManifestModule.ModuleVersionId.ToString();Need(Hash(File.ReadAllBytes(inputPath))==output.inputSha256,"Witness input changed during native capture");File.WriteAllText(outputPath,JsonUtility.ToJson(output,true));Debug.Log("[NativeSourceMathWitness] result=Passed burst_verified=true look="+looks.Length+" aria="+arias.Length+" scope=ReferenceOnly");
 }
}}
